package com.andye.warmod.antiair.client;import com.andye.warmod.antiair.network.*;import java.util.*;public final class ClientAntiAirVisualManager{public static final ClientAntiAirVisualManager INSTANCE=new ClientAntiAirVisualManager();private final Map<UUID,AntiAirVisualState> active=new LinkedHashMap<>();private ClientAntiAirVisualManager(){}public synchronized void launch(ClientboundAntiAirLaunchPayload p){while(active.size()>=2048)active.remove(active.keySet().iterator().next());active.put(p.interceptorId(),new AntiAirVisualState(p));}public synchronized void lock(ClientboundAntiAirRouteLockPayload p){var s=active.get(p.interceptorId());if(s!=null)s.lock(p);}public synchronized void phase(ClientboundAntiAirPhasePayload p){var s=active.get(p.interceptorId());if(s!=null)s.phase(p);}public synchronized void remove(UUID id){active.remove(id);}public synchronized List<AntiAirVisualState> snapshot(){return List.copyOf(active.values());}public synchronized void clear(){active.clear();}}